use std::fs

struct Bst {
    key: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

fn height_of(t: Bst, n: int) -> int {
    if n < 0 {
        return 0
    }
    let l = height_of(t, t.left[n as usize])
    let r = height_of(t, t.right[n as usize])
    if l > r { l + 1 } else { r + 1 }
}

fn walk(t: Bst, n: int, out: Vec<string>) -> Vec<string> {
    if n < 0 {
        return out
    }
    let mut o = walk(t, t.left[n as usize], out)
    o.push("${t.key[n as usize]}")
    walk(t, t.right[n as usize], o)
}

fn main() {
    let mut t = Bst { key: [], left: [], right: [], root: -1 }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur = t.root
            let mut parent: int = -1
            let mut went_left = false
            let mut found = false
            while cur >= 0 {
                let k = t.key[cur as usize]
                if k == x {
                    found = true
                    break
                }
                parent = cur
                if x < k {
                    went_left = true
                    cur = t.left[cur as usize]
                } else {
                    went_left = false
                    cur = t.right[cur as usize]
                }
            }
            if found {
                println("dup")
            } else {
                let idx: int = t.key.len() as int
                t.key.push(x)
                t.left.push(-1)
                t.right.push(-1)
                if parent < 0 {
                    t.root = idx
                } else if went_left {
                    t.left[parent as usize] = idx
                } else {
                    t.right[parent as usize] = idx
                }
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur = t.root
            let mut found = false
            while cur >= 0 {
                let k = t.key[cur as usize]
                if k == x {
                    found = true
                    break
                }
                if x < k {
                    cur = t.left[cur as usize]
                } else {
                    cur = t.right[cur as usize]
                }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur = t.root
            let mut parent: int = -1
            let mut went_left = false
            let mut found = false
            while cur >= 0 {
                let k = t.key[cur as usize]
                if k == x {
                    found = true
                    break
                }
                parent = cur
                if x < k {
                    went_left = true
                    cur = t.left[cur as usize]
                } else {
                    went_left = false
                    cur = t.right[cur as usize]
                }
            }
            if !found {
                println("missing")
            } else {
                if t.left[cur as usize] >= 0 && t.right[cur as usize] >= 0 {
                    let mut sp = cur
                    let mut s = t.right[cur as usize]
                    let mut sl = false
                    while t.left[s as usize] >= 0 {
                        sp = s
                        sl = true
                        s = t.left[s as usize]
                    }
                    t.key[cur as usize] = t.key[s as usize]
                    parent = sp
                    went_left = sl
                    cur = s
                }
                let child = if t.left[cur as usize] >= 0 { t.left[cur as usize] } else { t.right[cur as usize] }
                if parent < 0 {
                    t.root = child
                } else if went_left {
                    t.left[parent as usize] = child
                } else {
                    t.right[parent as usize] = child
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            let o = walk(t, t.root, [])
            if o.len() == 0 {
                println("<empty>")
            } else {
                println(o.join(" "))
            }
        } else if cmd == "height" {
            println("${height_of(t, t.root)}")
        } else if cmd == "min" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                while t.left[c as usize] >= 0 {
                    c = t.left[c as usize]
                }
                println("${t.key[c as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                while t.right[c as usize] >= 0 {
                    c = t.right[c as usize]
                }
                println("${t.key[c as usize]}")
            }
        }
    }
}

